import {copy} from './music.js';
import {SECTION_KINDS,sectionAt,updateSection,sectionTemplate,planSection} from './sections.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),label=s=>`第 ${s.start/4+1} 小节 · ${s.length/4} 小节`;
export function createSectionUI({getProject,getRevision,getSelected,commit,protectedChange,modal,toast}){
 function guard(at,id){if(at!==getRevision()||id!==getSelected()){const error=$('#section-error');if(error)error.textContent='工程或段落选择已改变，请关闭窗口后重新操作。';$('#section-apply').disabled=true;return false}return true}
 function finish(next,id,at,selection,label){if(!guard(at,selection))return;protectedChange(()=>{if(!guard(at,selection))return;if(commit(next,id)){$('#modal').close();toast(label+'，可一次撤销。没有开始播放。')}},label+'前');}
 function manager(){const p=getProject();modal('歌曲段落 · 先搭一个骨架',`<div class="section-form"><p>段落是整首歌曲的命名时间窗，不是新音源。把“主歌 / 副歌”标在轨道上，再整体复制或移动里面的所有轨道音块。</p><div class="section-presets"><button class="quiet" data-section-template="verse-chorus"><strong>主歌 → 副歌</strong><small>两段等长 · 只加标签</small></button><button class="quiet" data-section-template="four-parts"><strong>前奏 → 主歌 → 副歌 → 尾奏</strong><small>四段等长 · 只加标签</small></button></div><div class="section-list">${(p.sections||[]).map(s=>`<button class="quiet" data-section-edit="${s.id}"><span><strong>${escape(s.name)}</strong><small>${label(s)}</small></span><span>编辑与编排 →</span></button>`).join('')||'<p>还没有段落。可以选一个骨架，也可以自己添加。</p>'}</div><div class="modal-notice">骨架只命名已有时间窗，不生成或复制音乐；如果已有标签，应用骨架会明确替换它们。段落不重叠，最短 1 小节。整个工程当前最多 64 小节。</div></div>`,'<button class="quiet" data-close>关闭</button><button class="accent" id="section-new">＋ 自定义段落</button>');$('#section-new').onclick=()=>editLabel();document.querySelectorAll('[data-section-edit]').forEach(b=>b.onclick=()=>editLabel(b.dataset.sectionEdit));document.querySelectorAll('[data-section-template]').forEach(b=>b.onclick=()=>template(b.dataset.sectionTemplate));}
 function template(kind){const before=copy(getProject()),at=getRevision(),selection=getSelected(),next=sectionTemplate(before,kind);modal('歌曲骨架 · 只改标签',`<div class="section-form"><p>以下 ${next.sections.length} 个标签将替换当前 ${before.sections?.length||0} 个段落标签。所有音符、音块、共享关系、音色与混音保持原样。</p><div class="section-list">${next.sections.map(s=>`<div><strong>${escape(s.name)}</strong><small>${label(s)}</small></div>`).join('')}</div><div id="section-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="section-apply">应用骨架，不改音乐</button>');$('#section-apply').onclick=()=>finish(next,next.sections[0].id,at,selection,'已应用歌曲骨架');}
 function editLabel(id){const before=copy(getProject()),at=getRevision(),selection=getSelected(),s=id?sectionAt(before,id):{name:'新段落',kind:'custom',start:0,length:4};let result;
  modal(id?'段落设置 · 标签与音乐分开':'添加一个歌曲段落',`<div class="section-form"><p>修改这里的起点、长度或名称只移动标签，不移动音乐。要连音乐一起移动，请用“整体编排”。</p><label class="modal-label" for="section-name">段落名称</label><input id="section-name" value="${escape(s.name)}" maxlength="40"><div class="section-fields"><label for="section-kind">段落类型<select id="section-kind">${Object.entries(SECTION_KINDS).map(([key,name])=>`<option value="${key}" ${key===s.kind?'selected':''}>${name}</option>`).join('')}</select></label><label for="section-start">起始小节<input id="section-start" type="number" min="1" max="${before.bars}" step="1" value="${s.start/4+1}"></label><label for="section-length">长度（小节）<input id="section-length" type="number" min="1" max="${before.bars}" step="1" value="${s.length/4}"></label></div><div id="section-summary" class="section-summary"></div><div id="section-error" role="status" class="export-progress"></div></div>`,`<button class="quiet" data-close>取消</button>${id?'<button class="quiet" id="section-arrange">整体编排…</button><button class="quiet danger" id="section-delete">仅删除标签</button>':''}<button class="accent" id="section-apply">保存标签</button>`);
  const update=()=>{try{result=updateSection(before,{id,name:$('#section-name').value,kind:$('#section-kind').value,start:(+$('#section-start').value-1)*4,length:+$('#section-length').value*4});$('#section-summary').textContent=label(sectionAt(result.project,result.sectionId))+' · 不改变任何音乐';$('#section-error').textContent='';$('#section-apply').disabled=JSON.stringify(result.project)===JSON.stringify(before)}catch(e){result=null;$('#section-error').textContent=e.message;$('#section-summary').textContent='调整后再保存，当前工程尚未改变。';$('#section-apply').disabled=true}};
  for(const key of ['name','kind','start','length'])$('#section-'+key).oninput=update;$('#section-apply').onclick=()=>result&&finish(result.project,result.sectionId,at,selection,'已保存段落标签');if(id){$('#section-arrange').onclick=()=>guard(at,selection)&&arrange(id);$('#section-delete').onclick=()=>{const r=planSection(before,id,{action:'label-delete'});finish(r.project,null,at,selection,'已删除标签，音乐保持')}}update();
 }
 function arrange(id=getSelected()){
  const before=copy(getProject()),at=getRevision(),selection=getSelected();let s;try{s=sectionAt(before,id)}catch(e){return toast(e.message)}let result;
  modal('整体编排 · 所有轨道一起走',`<div class="section-form"><p><strong>${escape(s.name)}</strong> · ${label(s)}。包含静音音块，不改变其静音状态。先查看影响，再一次应用。</p><label class="modal-label" for="section-action">这次要做什么</label><select id="section-action"><option value="copy">复制音乐与标签 · 原段保持</option><option value="move">移动音乐与标签 · 原处留白</option><option value="clear">清空这段音乐 · 保留标签与时间</option></select><div class="section-fields"><label for="section-target">目标起始小节<input id="section-target" type="number" min="1" max="64" step="1" value="${(s.start+s.length)/4+1}"></label><label for="section-copy-name">目标段落名称<input id="section-copy-name" maxlength="40" value="${escape(s.name+' · 副本')}"></label></div><label class="check-label"><input id="section-linked" type="checkbox">复制完整共享块时保持关联（边界切片始终独立）</label><label class="check-label"><input id="section-extend" type="checkbox">超出当前长度时延长为留白（4 / 8 / 16 / 32 / 64 小节）</label><div id="section-summary" class="section-summary"></div><div class="modal-notice">目标必须在全部轨道与标签上都留空，包括没有音符的音块；不覆盖，不挤走后面的内容，不自动重排。跨边界音块和长音会切分，过短片段整组拒绝。移动完整共享块保持关联；普通复制默认独立。源库、音色、混音与练习范围保持，练习范围不会跟随段落移动。</div><div id="section-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="section-apply">应用这次编排</button>');
  const update=()=>{const action=$('#section-action').value,clear=action==='clear';if(action==='move'&&$('#section-copy-name').value===s.name+' · 副本')$('#section-copy-name').value=s.name;if(action==='copy'&&$('#section-copy-name').value===s.name)$('#section-copy-name').value=s.name+' · 副本';$('#section-target').disabled=clear;$('#section-copy-name').disabled=clear;$('#section-extend').disabled=clear;$('#section-linked').disabled=action!=='copy';try{result=planSection(before,id,{action,start:(+$('#section-target').value-1)*4,name:$('#section-copy-name').value,linked:action==='copy'&&$('#section-linked').checked,extend:!clear&&$('#section-extend').checked});const r=result.report;$('#section-summary').innerHTML=`<span class="eyebrow">静音编排预览</span><h3>${clear?'清空原处音乐':action==='copy'?'保留原段，并复制到新位置':'移动到新位置，原处留白'}</h3><div class="section-map">${result.project.sections.map(x=>`<span style="left:${x.start/(result.project.bars*4)*100}%;width:${x.length/(result.project.bars*4)*100}%" class="${x.id===result.sectionId?'active':''}">${escape(x.name)}</span>`).join('')}</div><div class="performance-badges"><span>${r.tracks} 轨 · ${r.clips} 个源音块</span><span>切分 ${r.crossingClips} 块 / ${r.crossingNotes} 长音</span><span>新增 ${r.addedNotes} / 移除 ${r.removedNotes} 音符标识</span><span>关联复制 ${r.linkedCopies} 块</span><span>独立片段 ${r.detached} 块</span>${r.extended?`<span>明确延长为 ${result.project.bars} 小节</span>`:''}</div><p>跨界长音分段后重新起音，不是无缝音频切片。${r.limitedTiming?'有 '+r.limitedTiming+' 个切片音符的微偏移受新边界限制。':''}当前工程尚未改变。</p>`;$('#section-error').textContent='';$('#section-apply').disabled=JSON.stringify(result.project)===JSON.stringify(before)}catch(e){result=null;$('#section-summary').textContent='暂时不能应用，当前工程没有改变。';$('#section-error').textContent=e.message;$('#section-apply').disabled=true}};
  for(const key of ['action','target','copy-name','linked','extend'])$('#section-'+key).oninput=update;$('#section-apply').onclick=()=>result&&finish(result.project,result.sectionId,at,selection,'已整体编排段落');update();
 }
 return{manager,editLabel,arrange};
}
